// Custom shape for rounded corners only on specific sides
struct RoundedCorners: Shape {
    var topLeft: CGFloat = 0.0
    var topRight: CGFloat = 0.0
    var bottomLeft: CGFloat = 0.0
    var bottomRight: CGFloat = 0.0

    func path(in rect: CGRect) -> Path {
        let path = UIBezierPath(
            roundedRect: rect,
            byRoundingCorners: [
                topLeft > 0 ? .topLeft : [],
                topRight > 0 ? .topRight : [],
                bottomLeft > 0 ? .bottomLeft : [],
                bottomRight > 0 ? .bottomRight : []
            ].reduce([]) { $0.union($1) },
            cornerRadii: CGSize(
                width: max(topLeft, topRight, bottomLeft, bottomRight),
                height: max(topLeft, topRight, bottomLeft, bottomRight)
            )
        )
        return Path(path.cgPath)
    }
}








